// Idempotencia (briefing): mismo order_id/payment_id no reenvia el correo.
// Reintentos de red del backend, o process-payment + webhook para la misma orden.
const d = $json.body ?? $json;
const key = String(d.payment_id || d.order_id || '');
if (!key) { throw new Error('payload sin order_id/payment_id'); }

const store = $getWorkflowStaticData('global');
store.procesados = store.procesados || {};
if (store.procesados[key]) {
  return [{ json: { duplicate: true, key } }];
}
store.procesados[key] = new Date().toISOString();

// Poda: conserva solo los ultimos 500 para no crecer sin limite.
const claves = Object.keys(store.procesados);
if (claves.length > 500) {
  claves.sort((a, b) => store.procesados[a].localeCompare(store.procesados[b]));
  for (const k of claves.slice(0, claves.length - 500)) delete store.procesados[k];
}

// Formateo para las plantillas de correo.
const money = (n) => 'S/ ' + Number(n).toFixed(2);
const filas = (d.items || []).map((i) =>
  `<tr><td>${i.name}</td><td align="center">${i.quantity}</td><td align="right">${money(i.price_pen)}</td><td align="right">${money(i.price_pen * i.quantity)}</td></tr>`
).join('');
const fecha = new Date(d.payment_date || Date.now()).toLocaleString('es-PE', { timeZone: 'America/Lima' });

return [{ json: {
  duplicate: false,
  order_id: d.order_id,
  payment_id: d.payment_id,
  customer_name: d.customer_name || 'cliente',
  customer_email: d.customer_email,
  total_pen: d.total_pen,
  total_fmt: money(d.total_pen),
  fecha_fmt: fecha,
  items_rows_html: filas,
} }];
